import{_ as n,o as e,c as a,a2 as r}from"./chunks/framework.BBd5PKnH.js";const i="/dev-notes/assets/Screenshot%202026-10-05%20at%2022.03.08.BV3gte_o.png",o="/dev-notes/assets/Screenshot%202026-10-05%20at%2022.12.18.Cql-ulOR.png",l="/dev-notes/assets/Screenshot%202026-10-05%20at%2022.13.35.mVsYgtrp.png",c="/dev-notes/assets/Screenshot%202026-10-05%20at%2022.44.35.DmqOpRld.png",s="/dev-notes/assets/Screenshot%202026-10-05%20at%2022.47.35.Rb9RueS1.png",u="/dev-notes/assets/Screenshot%202026-10-05%20at%2022.55.01.BijE51Mi.png",k=JSON.parse('{"title":"VPC, Subnet, NACL và Security Group trên AWS","description":"","frontmatter":{},"headers":[],"relativePath":"notes/aws/vpc_subnet_sec_group.md","filePath":"notes/aws/vpc_subnet_sec_group.md"}'),h={name:"notes/aws/vpc_subnet_sec_group.md"};function g(p,t,d,b,m,v){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="vpc-subnet-nacl-va-security-group-tren-aws" tabindex="-1">VPC, Subnet, NACL và Security Group trên AWS <a class="header-anchor" href="#vpc-subnet-nacl-va-security-group-tren-aws" aria-label="Permalink to &quot;VPC, Subnet, NACL và Security Group trên AWS&quot;">​</a></h1><h2 id="vpc" tabindex="-1">VPC <a class="header-anchor" href="#vpc" aria-label="Permalink to &quot;VPC&quot;">​</a></h2><ul><li>Mỗi tài khoản AWS có thể tạo nhiều VPC (Virtual Private Cloud) — mỗi VPC là một mạng ảo riêng biệt.</li></ul><h2 id="internet-gateway" tabindex="-1">Internet Gateway <a class="header-anchor" href="#internet-gateway" aria-label="Permalink to &quot;Internet Gateway&quot;">​</a></h2><ul><li>Mỗi VPC muốn kết nối ra Internet cần gắn một <strong>Internet Gateway</strong>.</li></ul><h2 id="subnet" tabindex="-1">Subnet <a class="header-anchor" href="#subnet" aria-label="Permalink to &quot;Subnet&quot;">​</a></h2><p><img src="'+i+'" alt="Subnet"></p><ul><li><p>Subnet nằm trong VPC — một VPC có thể chứa nhiều subnet.</p></li><li><p>Có 2 loại: <strong>public subnet</strong> và <strong>private subnet</strong>, bản chất giống nhau, chỉ khác route table:</p><ul><li>Route table của public subnet có đường đi ra Internet qua Internet Gateway.</li><li>Route table của private subnet thì không.</li></ul></li><li><p><strong>Public IP</strong> được gắn cho các server nằm trong public subnet (thường là frontend).</p></li><li><p><strong>Private subnet</strong> chứa database và backend — không expose trực tiếp ra Internet.</p></li><li><p>Mỗi subnet được gắn vào đúng 1 route table và đúng 1 NACL. VD: Ví dụ một gói tin đi từ EC2 ở subnet private ra internet:</p><ul><li>Security group của EC2: có cho phép đi ra không? → OK</li><li>NACL của subnet: có cho phép đi ra không? → OK</li><li>Route table của subnet: 0.0.0.0/0 thì đi đâu? → tới NAT Gateway</li><li>NAT Gateway đưa gói tin ra internet.</li></ul></li></ul><h2 id="network-access-control-list-nacl" tabindex="-1">Network Access Control List (NACL) <a class="header-anchor" href="#network-access-control-list-nacl" aria-label="Permalink to &quot;Network Access Control List (NACL)&quot;">​</a></h2><p><img src="'+o+'" alt="NACL"></p><ul><li>NACL là bộ rule áp dụng vào subnet, quy định traffic nào được đi vào/đi ra.</li><li><strong>Stateless</strong>: phải định nghĩa rule theo cả hai chiều (IN/OUT) riêng biệt. Ví dụ: nếu chỉ định nghĩa rule cho phép IN ở port 80 mà không định nghĩa OUT cho port 80, request đi vào được nhưng response không đi ra lại được cho client — vì vậy phải định nghĩa cả hai chiều.</li><li>Mỗi subnet chỉ được gắn với <strong>1 NACL</strong> tại một thời điểm.</li><li>Rule có thể là <strong>allow</strong> hoặc <strong>deny</strong> (defined/allowed).</li></ul><h3 id="inbound-rule-cho-nacl" tabindex="-1">Inbound rule cho NACL <a class="header-anchor" href="#inbound-rule-cho-nacl" aria-label="Permalink to &quot;Inbound rule cho NACL&quot;">​</a></h3><p><img src="'+l+'" alt="Inbound rule NACL"></p><h2 id="security-group" tabindex="-1">Security Group <a class="header-anchor" href="#security-group" aria-label="Permalink to &quot;Security Group&quot;">​</a></h2><p><img src="'+c+'" alt="Security Group bảo vệ EC2"></p><ul><li>instance-level, gắn lên network interface của từn instance,</li><li>Đóng vai trò <strong>firewall</strong> bảo vệ các component nằm trong subnet (ví dụ: đang bảo vệ một EC2).</li><li><strong>Stateful</strong> — ngược lại với NACL: chỉ cần định nghĩa request chiều vào (IN) là đủ, response tự động được cho phép đi ra mà không cần định nghĩa thêm.</li><li>Chỉ có <strong>allow</strong>, không có <strong>deny</strong> như NACL.</li><li>Không có khái niệm <strong>order</strong> (thứ tự rule) như NACL.</li><li>Sec group không có khả năng Deny chỉ có Nacl mới có quyền Deny</li></ul><h3 id="vi-du-luong-traffic" tabindex="-1">Ví dụ luồng traffic <a class="header-anchor" href="#vi-du-luong-traffic" aria-label="Permalink to &quot;Ví dụ luồng traffic&quot;">​</a></h3><p><img src="'+s+'" alt="Ví dụ inbound/outbound Security Group"></p><ul><li><strong>Inbound</strong> đi vào: ví dụ người dùng gửi request đến cổng 80 → vào được cổng 80 → response tự động ra lại được cổng 80, không cần cấu hình gì thêm.</li><li><strong>Outbound</strong>: request từ EC2 đi ra — có thể gọi đến bất kỳ port nào, bất kỳ protocol nào (mặc định mở toàn bộ chiều ra).</li><li>Tóm lại: chiều ra (outbound) mặc định mở toang, còn chiều vào (inbound) thì bị giới hạn theo đúng port/source đã khai báo.</li></ul><h2 id="cidr" tabindex="-1">CIDR <a class="header-anchor" href="#cidr" aria-label="Permalink to &quot;CIDR&quot;">​</a></h2><ul><li>CIDR (Classless Inter-Domain Routing) dùng để định nghĩa dải địa chỉ IP cho VPC/subnet (ví dụ <code>10.0.0.0/16</code>), quyết định số lượng địa chỉ IP khả dụng trong mạng.</li></ul><h2 id="vi-du-set-up-virtual-network" tabindex="-1">Ví dụ: Set up Virtual Network <a class="header-anchor" href="#vi-du-set-up-virtual-network" aria-label="Permalink to &quot;Ví dụ: Set up Virtual Network&quot;">​</a></h2><p><img src="'+u+'" alt="Thiết lập Virtual Network mẫu"></p><p>Một thiết kế mạng mẫu gồm:</p><ul><li>1 public subnet (chứa frontend, có public IP, route ra Internet qua Internet Gateway).</li><li>2 private subnet (chứa backend/database, không có đường ra Internet trực tiếp).</li></ul>',25)])])}const C=n(h,[["render",g]]);export{k as __pageData,C as default};
